#[path = "../src/render.rs"]
mod render;

#[test]
fn cell_color_matches_js_surface_and_sea() {
    let ctx = render::RenderCtx::with_appearance(&FIELD, &TEMPERATURE, &RAINFALL, Some(&FLOW), 10, 10, 0.42f64, false, 55f64, 5f64, render::TerrainAppearance::js_reference());

    // Tight but not bit-exact -- Math.pow/exp/hypot vs. Rust's f64
    // equivalents can differ by a handful of ULPs, which compounds through
    // materialWeights' two-pass canopy closure. 1e-4 absolute per channel
    // (~0.025/255) is far tighter than anything visually perceptible and
    // still catches a genuine formula mismatch, matching this project's
    // "never widen a tolerance to hide a real bug" rule.
    const TOL: f64 = 1e-4;
    let mut worst: f64 = 0.0;
    for y in 0..10usize {
        for x in 0..10usize {
            let i = y * 10 + x;
            let (r, g, b) = render::cell_color(&ctx, x, y);
            let (er, eg, eb) = (EXPECTED_RGB[i * 3], EXPECTED_RGB[i * 3 + 1], EXPECTED_RGB[i * 3 + 2]);
            for (got, want, ch) in [(r, er, 'r'), (g, eg, 'g'), (b, eb, 'b')] {
                let d = (got - want).abs();
                worst = worst.max(d);
                assert!(d < TOL, "cell ({x},{y}) channel {ch}: got {got}, want {want}, diff {d}");
            }
        }
    }
    assert!(worst < TOL, "worst diff {worst}");
}


