#[test]
fn cell_color_matches_js_world_wrap() {
    let ctx = render::RenderCtx::with_appearance(&FIELD_2, &TEMPERATURE_2, &RAINFALL_2, Some(&FLOW_2), 12, 12, 0.42f64, true, 55f64, 5f64, render::TerrainAppearance::js_reference());

    const TOL: f64 = 1e-4;
    for y in 0..12usize {
        for x in 0..12usize {
            let i = y * 12 + x;
            let (r, g, b) = render::cell_color(&ctx, x, y);
            let (er, eg, eb) = (EXPECTED_RGB_2[i * 3], EXPECTED_RGB_2[i * 3 + 1], EXPECTED_RGB_2[i * 3 + 2]);
            for (got, want, ch) in [(r, er, 'r'), (g, eg, 'g'), (b, eb, 'b')] {
                let diff = (got - want).abs();
                assert!(diff < TOL, "cell ({x},{y}) channel {ch}: got {got}, want {want}, diff {diff}");
            }
        }
    }
}
